import { useState, useEffect } from "react";
import C from "../constants/colors";
import { MARKET_DATA } from "../constants/data";
import Card from "../components/ui/Card";
import TrendPill from "../components/ui/TrendPill";
import { useTranslation } from 'react-i18next';

function Dashboard({ user, setPage }) {
  const [weather, setWeather] = useState({ temp:32, humidity:72, description:"Partly cloudy", city:user.district||"Madurai", windSpeed:3.2, rain:0 });

  useEffect(() => {
    const WKEY = process.env.REACT_APP_WEATHER_API_KEY || "";
    if (!WKEY) return;
    navigator.geolocation?.getCurrentPosition(pos => {
      fetch(`https://api.openweathermap.org/data/2.5/weather?lat=${pos.coords.latitude}&lon=${pos.coords.longitude}&appid=${WKEY}&units=metric`)
        .then(r=>r.json()).then(d=>setWeather({ temp:Math.round(d.main.temp), humidity:d.main.humidity, description:d.weather[0].description, city:d.name, windSpeed:d.wind.speed, rain:d.rain?.["1h"]||0 })).catch(()=>{});
    });
  }, []);

  const bars = [
    { label:"Weather Risk", val:65, c:C.orange }, { label:"Disease Pressure", val:78, c:C.red },
    { label:"Soil Health", val:82, c:C.bg2 }, { label:"Pest Alert", val:55, c:C.amber },
  ];

  return (
    <div style={{ padding:22 }}>
      <div style={{ marginBottom:18, display:"flex", justifyContent:"space-between", alignItems:"flex-end" }}>
        <div>
          <h1 style={{ fontSize:21, fontWeight:600, color:C.text, margin:0 }}>👋 {t('welcome')}, {user.name.split(" ")[0]}!</h1>
          <p style={{ color:C.muted, fontSize:13, margin:"4px 0 0" }}>{user.district}, Tamil Nadu • 21 April 2026</p>
        </div>
        <div style={{ textAlign:"right" }}>
          <div style={{ fontSize:22, fontWeight:700, color:C.text }}>{weather.temp}°C ⛅</div>
          <div style={{ fontSize:12, color:C.muted }}>{weather.humidity}% humidity • {weather.description}</div>
        </div>
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:10, marginBottom:14 }}>
        {[
          { l: t('confluence'), v:"72%", s:"Medium Risk", c:C.orange },
          { l: t('active_alerts'), v:"3", s:"2 High Priority", c:C.red },
          { l: t('crops_tracked'), v:user.crops?.length||0, s:"Registered crops", c:C.bg2 },
          { l: t('farm_plots'), v:user.farms?.length||0, s:"Mapped on GPS", c:C.blue },
        ].map(s => (
          <Card key={s.l} style={{ padding:"12px 14px" }}>
            <div style={{ fontSize:10.5, color:C.muted, textTransform:"uppercase", letterSpacing:"0.05em", marginBottom:3 }}>{s.l}</div>
            <div style={{ fontSize:26, fontWeight:700, color:s.c }}>{s.v}</div>
            <div style={{ fontSize:11, color:C.muted, marginTop:1 }}>{s.s}</div>
          </Card>
        ))}
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"1.1fr 0.9fr", gap:14, marginBottom:14 }}>
        <Card>
          <div style={{ fontSize:13, fontWeight:600, color:C.text, marginBottom:10 }}>🎯 {t('risk_analysis')}</div>
          {[
            { t:"danger", msg:"Pest: Fall Armyworm spotted in Dindigul — check maize immediately", time:"2h ago" },
            { t:"warning", msg:"High humidity next 48hrs — blight risk HIGH for tomato & chilli", time:"5h ago" },
            { t:"success", msg:"PM-KISAN 19th installment released — check your bank account", time:"1d ago" },
          ].map((a,i) => (
            <div key={i} style={{ display:"flex", gap:9, padding:"8px 0", borderBottom:i<2?`1px solid ${C.border}`:"none" }}>
              <div style={{ width:8,height:8,borderRadius:"50%",background:a.t==="danger"?C.red:a.t==="warning"?C.orange:C.bg2,marginTop:5,flexShrink:0 }} />
              <div>
                <div style={{ fontSize:12.5, color:C.text, lineHeight:1.4 }}>{a.msg}</div>
                <div style={{ fontSize:11, color:C.muted, marginTop:2 }}>{a.time}</div>
              </div>
            </div>
          ))}
        </Card>
        <Card>
          <div style={{ fontSize:13, fontWeight:600, color:C.text, marginBottom:10 }}>🎯 Risk Analysis</div>
          {bars.map(b => (
            <div key={b.label} style={{ marginBottom:10 }}>
              <div style={{ display:"flex", justifyContent:"space-between", fontSize:12, marginBottom:3 }}>
                <span style={{ color:C.text }}>{b.label}</span>
                <span style={{ color:b.c, fontWeight:600 }}>{b.val}%</span>
              </div>
              <div style={{ height:5, background:"#e0ead4", borderRadius:3, overflow:"hidden" }}>
                <div style={{ height:"100%", width:`${b.val}%`, background:b.c, borderRadius:3 }} />
              </div>
            </div>
          ))}
        </Card>
      </div>

      <Card style={{ marginBottom:14 }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:10 }}>
          <div style={{ fontSize:13, fontWeight:600, color:C.text }}>📊 {t('market_movers')}</div>
          <button onClick={() => setPage("market")} style={{ fontSize:12, color:C.bg2, background:"none", border:"none", cursor:"pointer" }}>View All 42 Crops →</button>
        </div>
        <div style={{ display:"grid", gridTemplateColumns:"repeat(6,1fr)", gap:8 }}>
          {MARKET_DATA.filter(p=>p.trend!=="flat").slice(0,6).map(p => (
            <div key={p.crop} style={{ textAlign:"center", padding:"10px 6px", background:C.bg, borderRadius:8 }}>
              <div style={{ fontSize:10.5, color:C.muted, marginBottom:2 }}>{p.crop}</div>
              <div style={{ fontSize:13.5, fontWeight:700, color:C.text }}>₹{p.modal.toLocaleString()}</div>
              <TrendPill trend={p.trend} change={p.change} />
            </div>
          ))}
        </div>
      </Card>

      <div style={{ display:"grid", gridTemplateColumns:"repeat(4,1fr)", gap:10 }}>
        {[
          { icon:"🤖", label:"AI Agro Bot", sub:"Ask anything in Tamil", page:"bot", bg:`linear-gradient(135deg,${C.bg1},${C.dark})` },
          { icon:"🔬", label:"Disease Detect", sub:"Upload leaf photo", page:"disease", bg:`linear-gradient(135deg,#1a5090,#0d2d5e)` },
          { icon:"🗺️", label:"Farm Map", sub:"View your land", page:"map", bg:`linear-gradient(135deg,#1a5a40,#0a2e1e)` },
          { icon:"📈", label:"Market Prices", sub:"42 crops live", page:"market", bg:`linear-gradient(135deg,#8a4a10,#4a2408)` },
        ].map(c => (
          <div key={c.page} onClick={() => setPage(c.page)} style={{ background:c.bg, borderRadius:12, padding:"16px 14px", cursor:"pointer", border:"none" }}>
            <div style={{ fontSize:28, marginBottom:6 }}>{c.icon}</div>
            <div style={{ fontSize:14, fontWeight:600, color:"#fff" }}>{c.label}</div>
            <div style={{ fontSize:11.5, color:"rgba(255,255,255,0.65)", marginTop:2 }}>{c.sub} →</div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Dashboard;
